import {LOCATIONS,CAMPAIGN,makeRoom,makeEndless} from './rooms.js';
import {SAVE_KEY,defaultCareer,statsFor,SHELLS,buyUpgrade,settleRun,selectShell,isRoomUnlocked} from './progression.js';
import {createRun,step,runResult} from './simulation.js';
import {render,drawTitle} from './render.js';
import {createCareerStore} from './career-store.js';
import {createInputController} from './input.js';
import {esc,timeText,money,action,affordable,navigation,pausedRoomBanner,roomsMarkup,shopMarkup} from './ui.js';

const $=s=>document.querySelector(s), main=$('#main'),modal=$('#modal'),content=$('#modalContent');
let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error('blocked')},setItem(){throw Error('blocked')}};}
// The isolated QA server supplies memory-only storage; production never includes it.
if(window.sweepQaStorage)storage=window.sweepQaStorage;
let career,screen='title',run=null,paused=false,settlement=null,ctx=null,canvas=null,keys=new Set(),lastStamp=0,accumulator=0,lastHud=0,toastTimeout,audioContext,lastFocus=null,lastSeed='morning-light',roomDistrict=null,pendingStart=null,settling=false,starting=false,resetting=false,uiReady=false;
const store=createCareerStore(storage,{locks:navigator.locks,onWarning:warning,onChange:next=>{career=next;if(uiReady){settingsApply();updateNav();}}});
career=store.career;
const input=createInputController({canvas:()=>canvas,onGesture:clearInput,onChange:({touch})=>{const knob=$('.knob');if(knob)knob.style.transform=touch?`translate(${touch.dx*24}px,${touch.dy*24}px)`:'';}});
let remoteControl=null;

const medals=['','Bronze','Silver','Gold'];
const shells=()=>SHELLS.find(s=>s.id===career.shell)||SHELLS[0];
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function warning(s){$('#saveWarning').hidden=false;$('#saveWarning').textContent=s;}
if(store.status==='blocked')warning('Saving is unavailable in this browser. You can play, but progress will disappear when you leave.');
if(store.status==='recovered')warning('Your saved data could not be fully recovered. Valid progress was kept where possible.');
function save(change){return store.transact(change);}
function hasActiveRun(){return !!run && ['playing','finishing'].includes(run.phase) && !settlement;}
function updateNav(){const nav=$('#gameNav');if(!nav)return;nav.innerHTML=navigation(career,screen,hasActiveRun());bindActions(nav,false);}
function settingsApply(){document.body.classList.toggle('no-motion',career.settings.reducedMotion);$('#soundBtn').textContent=career.settings.muted?'♫̸':'♪';$('#soundBtn').setAttribute('aria-label',career.settings.muted?'Unmute sound':'Mute sound');$('#soundBtn').setAttribute('aria-pressed',String(!career.settings.muted));}
function sound(type,material){if(career.settings.muted||!audioContext)return;try{const t=audioContext.currentTime,osc=audioContext.createOscillator(),gain=audioContext.createGain();let f=type==='pickup'?({crumb:460,confetti:710,dust:280,stuck:360}[material]||500):type==='unload'?920:type==='finish'?660:type==='trinket'?1100:170;osc.type=material==='dust'?'sine':'triangle';osc.frequency.setValueAtTime(f,t);osc.frequency.exponentialRampToValueAtTime(f*(type==='full'?.65:1.55),t+.10);gain.gain.setValueAtTime(.035*career.settings.effects,t);gain.gain.exponentialRampToValueAtTime(.0001,t+(type==='finish'?.6:.16));osc.connect(gain);gain.connect(audioContext.destination);osc.start(t);osc.stop(t+.65);}catch{}}
function unlockAudio(){if(!audioContext)try{audioContext=new(window.AudioContext||window.webkitAudioContext)();}catch{}if(audioContext?.state==='suspended')audioContext.resume().catch(()=>{});}
document.addEventListener('pointerdown',unlockAudio,{once:true});document.addEventListener('keydown',unlockAudio,{once:true});
function clearInput(){if(remoteControl){const control=remoteControl;remoteControl=null;control.resolve({interrupted:true,...publicState()});}keys.clear();input.clear();}
function prepareScreen(name,keepScroll=false){clearInput();screen=name;paused=false;main.innerHTML='';canvas=null;ctx=null;document.body.dataset.screen=name;if(!keepScroll)window.scrollTo({top:0,behavior:'instant'});updateNav();}
function bindActions(root=main,focusHeading=true){if(root===main&&screen!=='play'&&hasActiveRun()&&!root.querySelector('.paused-room'))root.insertAdjacentHTML('afterbegin',pausedRoomBanner(run,screen==='shop'));root.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{Promise.resolve(act(b.dataset.action,b)).catch(error=>{console.error(error);notify('That action could not finish. Please try again.');});}));if(root===main&&screen!=='play'&&focusHeading){const heading=root.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}}
function title(){prepareScreen('title');const progressed=career.completed.length>0||hasActiveRun();main.innerHTML=`<section class="hero"><div><div class="eyebrow"><i class="dot"></i> BIG SATISFACTION. TINY ROBOT.</div><h1>A little mess.<br>A <em>lovely</em> clean.</h1><p>Guide a tiny vacuum robot through 24 messy rooms. Clean up, earn coins, and upgrade your robot. A fresh room is always one good clean away.</p><div class="button-row">${action('continue',progressed?'Continue your shift <span>↗</span>':'Start cleaning <span>↗</span>','primary')}${action('rooms','Browse rooms','ghost')}</div><div class="hero-note"><span>24 little transformations</span><span>No rush. No lives.</span></div><div class="locations-preview">${LOCATIONS.map(l=>`<span class="location-chip">${esc(l.name)}</span>`).join('')}</div></div><div class="hero-art"><canvas id="titleCanvas" width="960" height="640" aria-label="A cheerful mint vacuum robot cleaning a colorful room"></canvas><div class="art-label"><i class="dot"></i> READY FOR A FRESH START</div><div class="art-pill"><span><strong>Small robot. Big clean.</strong><br>Pull up a little happiness.</span><span>✦</span></div></div></section><section class="intro-strip"><div class="intro-cell"><span class="step-number">01</span><div><strong>Move to vacuum</strong><small>Steer your robot. It picks up mess automatically.</small></div></div><div class="intro-cell"><span class="step-number">02</span><div><strong>Dock to empty</strong><small>Park by a green station to make room in your bag.</small></div></div><div class="intro-cell"><span class="step-number">03</span><div><strong>Finish & upgrade</strong><small>Bank your coins. Upgrade your robot. Unlock the next room.</small></div></div></section>${progressed?`<div class="button-row">${action('new','New game','ghost')}${action('collection','Your little treasures','ghost')}</div>`:''}`;canvas=$('#titleCanvas');ctx=canvas.getContext('2d');bindActions();}
function rooms(district=roomDistrict){roomDistrict=Number.isInteger(district)?Math.max(0,Math.min(3,district)):Math.min(3,Math.floor((career.unlocked-1)/6));prepareScreen('rooms');main.innerHTML=roomsMarkup(career,roomDistrict);bindActions();}
function setupCanvas(){canvas=$('#gameCanvas');ctx=canvas.getContext('2d');const dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=960*dpr;canvas.height=640*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);const surface=$('.arena');surface.addEventListener('pointerdown',pointerDown);surface.addEventListener('pointermove',pointerMove);surface.addEventListener('pointerup',pointerUp);surface.addEventListener('pointercancel',pointerUp);surface.addEventListener('lostpointercapture',pointerUp);}
async function startRoom(id,seed){
  if(starting)return;starting=true;clearInput();
  try{const unlocked=await save(c=>{if(!isRoomUnlocked(c,id))return false;c.lastRoom=id;return true;});if(!unlocked){notify('Finish the previous room first.');return;}
    const room=id===0?makeEndless(seed??newSeed()):makeRoom(id);lastSeed=room.seed;
    run=createRun(room,statsFor(career.upgrades),`${Date.now()}-${crypto.randomUUID?.()||Math.random()}`);settlement=null;roomDistrict=room.location;playRoom();
  }finally{starting=false;}
}
function playRoom(){const room=run.room,id=room.id;prepareScreen('play');main.innerHTML=`<div class="play-head"><div><div class="eyebrow">${id===0?'ENDLESS SHIFT':`${esc(LOCATIONS[room.location].name)} / ROOM ${String(id).padStart(2,'0')}`}</div><h1>${esc(room.name)}</h1></div><div class="play-tools">${action('pause','Ⅱ Pause')}</div></div><section class="game-hud"><div class="clean-readout"><strong id="cleanPercent">0%</strong><span>ROOM<br>CLEAN</span></div><div id="bagMeter" class="bag-meter"><div class="bag-label"><strong id="bagText">Bag 0 / ${run.stats.capacity}</strong><span id="bagStatus">Room to spare</span></div><div class="progress-track"><div class="progress-fill" id="bagFill" style="width:0%"></div></div></div><div class="coin-hud"><small>SAVED COINS</small><span id="coinText">${money(career.coins)}</span><small id="pendingCoins" title="Added to your saved coins when you finish the room">+0 this room</small></div></section><div class="arena"><canvas id="gameCanvas" width="960" height="640" tabindex="0" aria-label="Cleaning room. Move with arrow keys or WASD, or hold the mouse to move. Suction and emptying are automatic. Escape pauses."></canvas><div class="joystick" aria-hidden="true"><div class="knob"></div></div><div class="touch-hint">Drag to glide</div></div><div class="game-bottom"><p id="gameTip">${esc(room.tip)}</p><details><summary>Room details</summary><div class="stat-details"><span id="elapsed">0:00</span><br>Gold ${timeText(room.goldTime)} · Silver ${timeText(room.silverTime)}<br>${id===0?`Seed: ${esc(room.seed)}<br>`:''}95% clean = finished</div></details></div>`;setupCanvas();bindActions();canvas.focus({preventScroll:true});lastStamp=performance.now();accumulator=0;lastHud=0;gameHUD();}
async function requestStart(id,seed){
  if(hasActiveRun()){
    if(run.room.id===id && id!==0)return playRoom();
    pendingStart={id,seed};
    if(modal.open)modal.close();
    openModal(`<h2 id="modalTitle">Start another room?</h2><p>Your unfinished cleaning and this room’s coins will be discarded. Completed rooms and purchases are already saved.</p><div class="button-row">${action('resume','Keep this room','primary')}${action('switch-confirm','Start new room')}</div>`);
    return;
  }
  return startRoom(id,seed);
}

function pointerDown(e){if(screen!=='play'||paused||run?.phase!=='playing')return;input.pointerDown(e);}
function pointerMove(e){input.pointerMove(e);}
function pointerUp(e){input.pointerUp(e);}
function movement(){return remoteControl?{x:remoteControl.x,y:remoteControl.y}:input.movement(run.robot,keys);}
function gameHUD(){if(!run||screen!=='play')return;const r=run,b=r.robot,pct=Math.min(100,Math.floor(r.percent*100)),fill=b.bag/r.stats.capacity;$('#cleanPercent').textContent=pct+'%';$('#bagText').textContent=`Bag ${b.bag} / ${r.stats.capacity}`;$('#bagFill').style.width=(fill*100)+'%';$('#bagStatus').textContent=r.unloading?'Emptying…':r.full?'Full → dock':fill>=.8?'Dock soon':'Room to spare';$('#bagMeter').classList.toggle('full',fill>=.8);$('#coinText').textContent=money(career.coins);$('#pendingCoins').textContent=`+${money(r.coins+b.bagValue)} this room`;$('#elapsed').textContent=timeText(r.time);let tip=r.room.tip;if(r.phase==='finishing')tip='The finishing touch. Every last corner, lovely.';else if(r.unloading)tip='Lovely haul! Keep close to the collection station while it empties.';else if(r.full)tip='Bag full. Follow the dock marker — your robot still moves normally.';else if(fill>=.8)tip='Nearly full. Park beside a collection station to empty automatically.';else if(r.percent>=.8)tip='Almost lovely. Follow the small golden rings to the remaining mess.';else if(r.room.id===1&&r.collectedCount<8)tip=window.innerWidth<=660||window.matchMedia?.('(pointer: coarse)').matches?'Drag the pad or room to glide. Vacuuming is automatic.':'WASD / arrows, or hold and drag. Your robot vacuums automatically.';else if(r.room.id===1&&r.time<30)tip='Dock to empty your bag. Reach 95% clean to finish, earn coins, and open the next room.';$('#gameTip').textContent=tip;}
async function completed(){if(settling||settlement)return;settling=true;const finished=run;try{const reward=await save(c=>settleRun(c,runResult(finished)));if(run!==finished)return;settlement=reward;if(!reward.ok){run=null;settlement=null;rooms();notify(reward.message);return;}results();}catch(error){console.error(error);warning('This room’s reward could not be recorded. Keep the tab open and try again.');}finally{settling=false;}}
function results(){prepareScreen('result');const r=run,s=settlement;const next=r.room.id===24&&!career.endingSeen?'ending':r.room.id>0&&r.room.id<24?`room:${r.room.id+1}`:'endless';main.innerHTML=`<section class="result"><div class="eyebrow" style="justify-content:center">${esc(LOCATIONS[r.room.location].name)} · SHIFT COMPLETE</div><div class="result-icon">✦</div><h1>Look at you glow.</h1><p>${esc(r.room.name)} is looking lovely.<br>Another little corner of the world, made better.</p><div class="result-stats"><div class="result-stat"><strong>+${money(s.coins)}</strong><small>COINS EARNED</small></div><div class="result-stat"><strong>${timeText(r.time)}</strong><small>YOUR TIME</small></div><div class="result-stat"><strong>✦ ${medals[runResult(r).medal]}</strong><small>ROOM MEDAL</small></div></div>${s.newTrinket?`<div class="bonus-note">A keeper! ${esc(r.trinket.name)} is on your treasure shelf.</div>`:''}${s.newShell?`<div class="bonus-note">Fresh look unlocked: ${esc(s.newShell.name)}. Find it in Upgrades.</div>`:''}${s.endlessUnlocked?'<div class="bonus-note">All 24 rooms restored. Endless Shift is now open!</div>':''}<div class="button-row">${action(next,next==='ending'?'A little celebration ↗':next==='endless'?'Play Endless Shift ↗':'Next room ↗','primary')}${action('shop',affordable(career).length?'Buy a robot upgrade ↑':'View upgrades')}${action('replay',r.room.id===0?'Replay this seed':'Replay room','ghost')}</div><div class="button-row">${action('rooms','Choose a room','ghost')}${action('collection','Treasure shelf','ghost')}</div><p style="font-size:12px">${s.bonus?`${money(s.bonus)} first-time bonuses included. `:''}Replays earn cleaning coins; previous bonuses are never paid twice.</p></section>`;bindActions();sound('finish');$('#announcement').textContent=`Room complete. ${s.coins} coins earned. ${medals[runResult(r).medal]} medal.`;}
function shop(keepScroll=false){prepareScreen('shop',keepScroll);main.innerHTML=shopMarkup(career,hasActiveRun());bindActions(main,!keepScroll);}
function collection(){prepareScreen('collection');main.innerHTML=`<div class="page-head"><div><div class="eyebrow">THE THINGS WE FIND</div><h1>Your little treasures.</h1><p>${career.trinkets.length} / 24 keepsakes. Optional discoveries, forever yours.</p></div></div><div class="button-row">${action('rooms','Back to rooms','primary')}</div>${LOCATIONS.map((l,i)=>`<div class="section-head"><h2>${esc(l.name)}</h2></div><div class="shelf">${l.trinkets.map((t,j)=>{let found=career.trinkets.includes(i*6+j+1);return`<div class="trinket-card ${found?'':'missing'}"><span>${found?'✧':'?'}</span><small>${found?esc(t):`Hidden in room ${i*6+j+1}`}</small></div>`}).join('')}</div>`).join('')}`;bindActions();}
function newSeed(){return `${['sunny','mint','cosy','little','bright','coral'][Math.floor(Math.random()*6)]}-${Math.random().toString(36).slice(2,7)}`;}
function endless(){if(career.unlocked<25)return;prepareScreen('endless');main.innerHTML=`<section class="result"><div class="result-icon">∞</div><div class="eyebrow" style="justify-content:center">ENDLESS SHIFT</div><h1>Always a fresh start.</h1><p>A familiar feeling. A different little room.<br>Every seed creates the same layout, so your favorites are yours to keep.</p><form class="seed-form" id="seedForm"><input id="seedInput" aria-label="Room seed" value="${esc(newSeed())}" maxlength="40" required><button class="primary" type="submit">Start cleaning ↗</button></form><p style="font-size:12px">Rooms stay a comfortable size. Your upgrades come with you.</p><div class="button-row">${action('shop','Robot upgrades')}${action('rooms','Back to rooms','ghost')}</div></section>`;$('#seedForm').onsubmit=e=>{e.preventDefault();let seed=$('#seedInput').value.trim().slice(0,40);if(seed)requestStart(0,seed);};bindActions();}
async function ending(){if(career.completed.length<24)return;await save(c=>{c.endingSeen=true;});prepareScreen('ending');main.innerHTML=`<section class="result"><div class="eyebrow" style="justify-content:center">24 ROOMS. COUNTLESS LITTLE DIFFERENCES.</div><div class="ending-garden">⌂ <span>✦</span> ♧ <span>☀</span></div><h1>You made room<br>for something lovely.</h1><p>The workshop is ready for its next big idea.<br>The arcade can welcome another high score.<br>The greenhouse has room to grow.<br>And the rooftop? Ready for one more sunset.</p><p>Thank you for taking care of the little things.</p><div class="bonus-note">Endless Shift and your final robot shell are unlocked.</div><div class="button-row">${action('endless','Start an endless shift ↗','primary')}${action('collection','Admire your treasures')}${action('credits','Credits','ghost')}</div><div class="button-row">${action('rooms','Revisit your favorite room','ghost')}</div></section>`;bindActions();}
function openModal(html){lastFocus=document.activeElement;paused=screen==='play';clearInput();content.innerHTML=html;bindActions(content);modal.showModal();}
function closeModal(){modal.close();paused=false;clearInput();lastStamp=performance.now();accumulator=0;if(screen==='play')canvas?.focus({preventScroll:true});else if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});else main.querySelector('h1')?.focus({preventScroll:true});}
function pause(){if(screen!=='play'||!hasActiveRun()||modal.open)return;openModal(`<h2 id="modalTitle">Take a little breather.</h2><p>Your room and clock are paused. Browse freely, then pick up where you left off.</p><div class="button-row">${action('resume','Back to cleaning ↗','primary')}${action('shop','Robot upgrades')}${action('rooms','Browse rooms')}${action('settings','Settings')}${action('restart','Restart room','ghost')}${action('quit','Leave room','ghost')}</div>`);}
function settings(){if(modal.open)modal.close();openModal(`<h2 id="modalTitle">Your kind of calm.</h2><label class="setting-row">Sound effects<input id="muteSetting" type="checkbox" ${!career.settings.muted?'checked':''}></label><label class="setting-row">Effects volume<input id="volumeSetting" aria-label="Effects volume" type="range" min="0" max="1" step=".05" value="${career.settings.effects}"></label><label class="setting-row">Reduced motion<input id="motionSetting" type="checkbox" ${career.settings.reducedMotion?'checked':''}></label><p>Finished rooms, coins, and purchases save automatically. Browsing menus keeps your current room paused. Restarting, leaving a room, or closing the game discards unfinished cleaning.</p><div class="button-row">${action('resume','All set','primary')}${action('new','Reset career','ghost')}</div>`);$('#muteSetting').onchange=async e=>{const value=!e.target.checked;await save(c=>{c.settings.muted=value;});};$('#volumeSetting').onchange=async e=>{const value=Number(e.target.value);await save(c=>{c.settings.effects=value;});};$('#motionSetting').onchange=async e=>{const value=e.target.checked;await save(c=>{c.settings.reducedMotion=value;});};}
function credits(){if(modal.open)modal.close();openModal(`<h2 id="modalTitle">A little labor of love.</h2><div class="credit-list"><p><strong>Sweep Shift</strong><br>A tiny cleaning game by Nathan Norris.</p><p>Built with JavaScript, Canvas, and synthesized Web Audio. All game artwork is drawn by original code. No external runtime assets or libraries are required.</p><p>Created with AI assistance for implementation, design iteration, writing, and testing.</p><p>Thanks for making the world a little lovelier.</p></div><div class="button-row">${action('resume','Lovely.','primary')}</div>`);}
function confirmReset(){if(modal.open)modal.close();openModal(`<h2 id="modalTitle">A completely fresh start?</h2><p>This resets your rooms, coins, upgrades, medals, and treasures. Your current career cannot be restored afterward.</p><div class="button-row">${action('resume','Keep my career','primary')}${action('reset-confirm','Reset and start again')}</div>`);}
function continueShift(){
  if(hasActiveRun())return playRoom();
  if(career.completed.length===24&&!career.endingSeen)return ending();
  if(career.lastRoom===0&&career.unlocked===25)return endless();
  if(career.completed.includes(career.lastRoom)){if(career.unlocked===25)return rooms();return startRoom(career.unlocked);}
  return startRoom(career.lastRoom||career.unlocked);
}
function restorePurchaseFocus(id){const button=main.querySelector('[data-action="'+id+'"]');const target=button?.disabled?button.closest('article')?.querySelector('h2'):button;target?.focus({preventScroll:true});}
async function act(a,b){
  if(starting||settling||resetting)return;
  if(['rooms','shop','collection','title','resume-room','endless'].includes(a)&&modal.open)closeModal();
  if(a.startsWith('room:'))return requestStart(Number(a.split(':')[1]));
  if(a.startsWith('district:')){const y=window.scrollY;rooms(Number(a.split(':')[1]));main.querySelector('[data-action="'+a+'"]')?.focus({preventScroll:true});window.scrollTo({top:y,behavior:'instant'});return;}
  if(a.startsWith('buy:')){b.disabled=true;const result=await save(c=>buyUpgrade(c,a.split(':')[1]));if(screen==='shop'){shop(true);restorePurchaseFocus(a);}if(result.ok)sound('unload');return notify(result.message);}
  if(a.startsWith('shell:')){const result=await save(c=>selectShell(c,a.split(':')[1]));if(screen==='shop'){shop(true);restorePurchaseFocus(a);}return notify(result.message);}
  switch(a){
    case'title':title();break;case'continue':return continueShift();case'rooms':rooms();break;case'shop':shop();break;case'collection':collection();break;case'endless':endless();break;case'ending':return ending();case'pause':pause();break;case'resume':closeModal();break;case'resume-room':if(hasActiveRun())playRoom();else rooms();break;case'settings':settings();break;case'credits':credits();break;case'new':confirmReset();break;
    case'reset-confirm':closeModal();resetting=true;clearInput();try{await save(c=>Object.assign(c,defaultCareer()));run=null;settlement=null;roomDistrict=0;return await startRoom(1);}finally{resetting=false;}
    case'replay':return requestStart(run.room.id,run.room.seed);
    case'restart':case'quit':{const restart=a==='restart';modal.close();openModal(`<h2 id="modalTitle">${restart?'Restart this room?':'Leave this room?'}</h2><p>Only this unfinished room’s cleaning and coins will be discarded. Your completed rooms and upgrades are saved.</p><div class="button-row">${action('resume','Keep cleaning','primary')}${action(restart?'restart-confirm':'quit-confirm',restart?'Restart room':'Leave room')}</div>`);break;}
    case'restart-confirm':closeModal();return startRoom(run.room.id,run.room.seed);
    case'quit-confirm':closeModal();run=null;settlement=null;rooms();break;
    case'switch-confirm':{const next=pendingStart;pendingStart=null;closeModal();if(next)return startRoom(next.id,next.seed);break;}
  }
}
modal.addEventListener('cancel',e=>{e.preventDefault();closeModal();});
$('#homeLink').onclick=e=>{e.preventDefault();if(screen==='play')pause();else title();};$('#soundBtn').onclick=async()=>{unlockAudio();await save(c=>{c.settings.muted=!c.settings.muted;});};$('#settingsBtn').onclick=settings;$('#creditsBtn').onclick=credits;
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Escape'){e.preventDefault();if(e.repeat)return;if(modal.open)closeModal();else pause();return;}if(screen!=='play'||modal.open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key===' '&&e.target.closest('button,a,summary'))return;if(remoteControl)clearInput();const key=e.key.length===1?e.key.toLowerCase():e.key;if(['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(key)){e.preventDefault();keys.add(key);}});
document.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>{clearInput();pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();pause();}lastStamp=performance.now();accumulator=0;});
function frame(stamp){if(remoteControl&&stamp>=remoteControl.until){const control=remoteControl;remoteControl=null;control.resolve({interrupted:false,...publicState()});}const delta=Math.min(.1,(stamp-(lastStamp||stamp))/1000);lastStamp=stamp;if(screen==='title'&&ctx)drawTitle(ctx,stamp/1000,career.settings.reducedMotion);else if(screen==='play'&&run&&ctx){if(!paused&&!starting&&!settling&&!resetting&&!document.hidden){accumulator+=delta;let input=movement();while(accumulator>=1/120){step(run,1/120,input);accumulator-=1/120;}for(const e of run.events){sound(e.type,e.material);if(e.type==='trinket')notify(`Found: ${run.trinket.name}!`);if(e.type==='unload')notify(`Bag emptied. ${e.value} coins ready to bank when you finish.`);if(e.type==='full')$('#announcement').textContent='Bag full. Move to a collection station.';}run.events=[];if(run.phase==='complete'){completed();requestAnimationFrame(frame);return;}}
    render(ctx,run,{time:stamp/1000,reducedMotion:career.settings.reducedMotion,shellColor:shells().color,pointer:input.pointer});if(stamp-lastHud>100){gameHUD();lastHud=stamp;}}
  requestAnimationFrame(frame);
}
// Optional browser-agent input uses the live movement loop; it cannot award progress.
function publicState(){return{screen,paused:paused||(hasActiveRun()&&screen!=='play'),room:run?{id:run.room.id,name:run.room.name,seed:run.room.seed}:null,phase:run?.phase,robot:run?{x:run.robot.x,y:run.robot.y,bag:run.robot.bag,capacity:run.stats.capacity}:null,percent:run?.percent,roomCoins:run?.coins,time:run?.time,career:JSON.parse(JSON.stringify(career))};}
const modelContext=document.modelContext;
if(modelContext?.registerTool){
  const lifecycle=new AbortController();
  const tools=[
    {name:'read_sweep_state',description:'Read the current room, robot, cleaning progress, and saved career.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:publicState},
    {name:'move_robot',description:'Hold a direction for up to four real seconds, using normal movement, collision, suction, and bag rules. A real input or pause interrupts this movement.',inputSchema:{type:'object',properties:{x:{type:'number',minimum:-1,maximum:1},y:{type:'number',minimum:-1,maximum:1},seconds:{type:'number',minimum:.05,maximum:4}},required:['x','y','seconds'],additionalProperties:false},execute:input=>{if(screen!=='play'||paused||document.hidden||run?.phase!=='playing'||remoteControl)throw Error('The robot is not available to move.');if(!input||![input.x,input.y,input.seconds].every(Number.isFinite)||Math.abs(input.x)>1||Math.abs(input.y)>1||input.seconds<.05||input.seconds>4)throw Error('Use a direction from -1 to 1 and a duration of 0.05–4 seconds.');clearInput();return new Promise(resolve=>{remoteControl={x:input.x,y:input.y,until:performance.now()+input.seconds*1000,resolve};});}},
    {name:'open_sweep_room',description:'Start an unlocked room from between-room screens, using the ordinary room-selection action.',inputSchema:{type:'object',properties:{id:{type:'integer',minimum:0,maximum:24},seed:{type:'string',maxLength:40}},required:['id'],additionalProperties:false},execute:async input=>{if(hasActiveRun()||modal.open||!Number.isInteger(input?.id)||!isRoomUnlocked(career,input.id))throw Error('This room is unavailable. Finish or leave the active room first.');await startRoom(input.id,input.seed);return publicState();}}
  ];
  for(const tool of tools)try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
  window.addEventListener('pagehide',()=>{clearInput();lifecycle.abort();},{once:true});
}
window.addEventListener('storage',async e=>{if(e.key!==SAVE_KEY&&e.key!==null)return;const previous=career;await store.sync();const reset=career.completed.length<previous.completed.length||Object.keys(career.upgrades).some(key=>career.upgrades[key]<previous.upgrades[key]);if(run&&(reset||!isRoomUnlocked(career,run.room.id))){if(modal.open)closeModal();run=null;settlement=null;roomDistrict=null;rooms();notify('Your career changed in another tab. This view now matches the latest save.');return;}if(screen==='shop')shop(true);else if(screen==='rooms')rooms();else if(screen==='play')gameHUD();});
if(store.status==='new'&&window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)await save(c=>{c.settings.reducedMotion=true;});
uiReady=true;settingsApply();title();requestAnimationFrame(frame);
